message.content:
{
  "candidate_edge_types": [
    {
      "name": "VERIFIES_EQUIVALENCE_WITH_REFERENCE_IMPLEMENTATION",
      "definition": "A verification step compares the observable outputs (modified data files and console output) produced by the candidate reimplementation against those produced by the original reference implementation for identical inputs, in order to establish behavioral equivalence.",
      "source_description": "An execution result produced by the newly written candidate program for a given input.",
      "target_description": "The corresponding execution result of the original reference program for the same input, used as the correctness oracle."
    },
    {
      "name": "DERIVES_IMPLEMENTATION_FROM_OBSERVED_REFERENCE_BEHAVIOR",
      "definition": "The agent constructs or revises its own implementation by generalizing the behavior it directly observed while executing the reference implementation.",
      "source_description": "An observation of the reference implementation's actual behavior (data mutations, record layouts, numeric conversion) under a given input.",
      "target_description": "The implementation action that reproduces that observed behavior in the new program."
    },
    {
      "name": "INVESTIGATES_DISCREPANCY_CAUSE",
      "definition": "A detected mismatch between candidate and reference behavior triggers a diagnostic action that inspects raw, low-level evidence to determine the underlying cause of the discrepancy.",
      "source_description": "A verification result reporting a difference between candidate and reference behavior.",
      "target_description": "A diagnostic action that examines raw underlying data or mechanism to explain the discrepancy."
    },
    {
      "name": "PROBES_REFERENCE_SEMANTICS_WITH_CONTROLLED_INPUT",
      "definition": "The agent feeds a deliberately crafted or boundary-case input to the reference implementation in order to characterize its exact behavior under that condition.",
      "source_description": "A controlled or boundary-case input created specifically to elicit a particular behavior from the reference implementation.",
      "target_description": "The observed behavior of the reference implementation for that controlled input."
    },
    {
      "name": "EXTENDS_VERIFICATION_COVERAGE_AFTER_SUCCESS",
      "definition": "A verification result in which the candidate implementation matched the reference implementation motivates the agent to add further variant or edge-case tests to broaden confidence.",
      "source_description": "A verification result showing that the candidate implementation matched the reference implementation.",
      "target_description": "An additional test designed to exercise a new input condition not previously covered."
    },
    {
      "name": "PRESERVES_REFERENCE_OUTPUT_AS_ORACLE",
      "definition": "The output produced by the reference implementation is copied to a durable location so that it can later serve as the comparison baseline for verifying the candidate implementation.",
      "source_description": "A reference implementation execution result that is to be used as ground truth.",
      "target_description": "A stored copy of that result retained as a verification oracle."
    },
    {
      "name": "VERIFIES_NO_STATE_CHANGE_AGAINST_BASELINE",
      "definition": "After an execution that is expected not to modify persistent state, the agent compares the current state against a preserved baseline copy to confirm that no files were changed.",
      "source_description": "An execution that was expected to leave the persistent state unmodified.",
      "target_description": "A comparison of the post-execution state against the preserved baseline confirming that the state is unchanged."
    }
  ]
}

